/**
 * Loud, actionable refusal text (printed to stderr by the shim).
 */
function refusalMessage(kind, violations) {
    var lines = [
        '',
        '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━',
        '🛑 GIT PUSH GUARD — agent-session git ' + kind + ' REFUSED (dmtools-agents#542)',
        '━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━',
