var CLOSING_KEYWORD_PATTERN = /\b(close[sd]?|fix(e[sd])?|resolve[sd]?)\s+(#[0-9]+|[A-Za-z0-9_.-]+\/[A-Za-z0-9_.-]+#[0-9]+|https?:\/\/\S+\/issues\/[0-9]+)/i;

