    ctx = ctx || {};
    var list = PROTECTED_BRANCHES.slice();
    var extra = (ctx.extraProtected || []);
    if (ctx.defaultBranch) extra = extra.concat([ctx.defaultBranch]);
    extra.forEach(function(b) {
        b = String(b || '').trim().replace(/^refs\/heads\//, '').replace(/^origin\//, '');
