 * Builds the effective protected-branch set.
 *
 * @param {Object} ctx
 * @param {string[]} [ctx.extraProtected]  - e.g. parsed FA_GIT_GUARD_PROTECTED_BRANCHES
 * @param {string}   [ctx.defaultBranch]   - remote default branch (origin/HEAD)
 */
