 *
 * @param {string} spec   - e.g. "main", "HEAD:main", ":main", "+refs/heads/x:refs/heads/y"
 * @param {Object} ctx
 * @param {string} [ctx.currentBranch] - checked-out branch, for bare "HEAD"
