                if (args.command.indexOf('git ls-remote --heads origin bug/PROJ-123') === 0) {
                    return '9a7e2aec9a7e2aec9a7e2aec9a7e2aec9a7e2aec\trefs/heads/bug/PROJ-123\n';
                }
