        }
    });

    var result = loaded.mod.action({
        ticket: { key: 'PROJ-123', fields: { labels: [] } },
        response: 'Some fix summary that should be pushed normally.'
    });

    assert.equal(result.success, true, 'non-blocking failures never fail the step');
