        commands: commands,
        cli: {
            cli_execute_command: function(args) {
                commands.push(args);
                if (args.command === 'git status --porcelain') return statusOutput || '';
                if (gateOutput !== undefined && args.command.indexOf('bash scripts/gate.sh') === 0) return gateOutput;
