        assert.equal(guard.evaluateCommit(['--message=resolves #8']).allowed, false);
        assert.equal(guard.evaluateCommit(['-mresolves #9']).allowed, false);
        assert.equal(guard.evaluateCommit(['-cm', 'resolves #10']).allowed, false);
    });

