        assert.equal(ok, false);
        assert.equal(m.comments.length, 1);
        assert.contains(m.comments[0].comment, 'Pre-push gate failed, changes NOT pushed:');
        assert.contains(m.comments[0].comment, '```');
        assert.contains(m.comments[0].comment, 'gate boom');
        // The comment carries the LAST 1500 chars of the error text.
        var fenced = m.comments[0].comment.split('```')[1];
        assert.ok(fenced.length <= 1502, 'error tail is sliced to 1500 chars, got ' + fenced.length);
