        assert.equal(guard.isJoinedShortMessage('-m'), false);
        assert.equal(guard.isJoinedShortMessage('--mx'), false);
        assert.equal(guard.isJoinedShortMessage('-cm'), false);

        assert.equal(guard.isFileValueFlag('-F'), true);
