        assert.deepEqual(part, { text: 'v', next: 2 });
        assert.deepEqual(guard.commitMessagePartAt(['-m'], 0, {}), { text: null, next: 1 });
        assert.deepEqual(guard.commitMessagePartAt(['--message='], 0, {}), { text: '', next: 1 });
