function parseReworkBaseBranch(prInfo) {
    try {
        var baseMatch = prInfo.match(/\*\*Branch\*\*:\s*`[^`]+`\s*→\s*`([^`]+)`/);
        return (baseMatch && baseMatch[1]) ? baseMatch[1].trim() : null;
    } catch (e) { return null; }
}

