    try {
        var prInfo = file_read({ path: 'input/' + ticketKey + '/pr_info.md' }) || '';
        var branchMatch = prInfo.match(/\*\*Branch\*\*:\s*`([^`]+)`/);
        return { prInfo: prInfo, headBranch: branchMatch ? branchMatch[1].trim() : null };
    } catch (e) {
